CREATE TABLE users(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(255) NOT NULL,email VARCHAR(255) NOT NULL UNIQUE,created_at TIMESTAMP NOT NULL DEFAULT now()) ENGINE=InnoDB
-- NEXT
CREATE TABLE categories(id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(255) NOT NULL UNIQUE) ENGINE=InnoDB
-- NEXT
CREATE TABLE products(id BIGINT PRIMARY KEY AUTO_INCREMENT,category_id INT NOT NULL,sku VARCHAR(255) NOT NULL UNIQUE,name VARCHAR(255) NOT NULL,price_cents BIGINT NOT NULL CHECK(price_cents>=0),stock INT NOT NULL DEFAULT 0 CHECK(stock>=0),name_lower VARCHAR(255) GENERATED ALWAYS AS (lower(name)) PERSISTENT,FOREIGN KEY(category_id) REFERENCES categories(id),INDEX products_category_id(category_id),INDEX products_name_lower(name_lower)) ENGINE=InnoDB
